/**
 * Sensitive local file references and import options for one profile.
 *
 * Each entry of `files` is a statement file or a directory. The operation
 * plans a directory into its importable files itself, in a deterministic
 * order, so every caller that names the same directory imports the same files.
 * The planned files of all entries together are held to
 * `MAX_LEDGER_IMPORT_FILES`.
 */
export type LedgerImportRequest = {
  profile_id: string;
  files: FileToken[];
  provider: LedgerProviderID;
  dry_run?: boolean;
  verify?: boolean;
  verify_source?: FileToken | null;
  period?: PublicPeriod | null;
  own_account_id?: string | null;
  expected_source_sha256?: ContentDigest[] | null;
  register_statement_account?: LedgerImportAccountRegistration | null;
};

