/**
 * The SHA-256 of the bytes parsed from one planned file, by its position in
 * the plan.
 *
 * The plan is the request's entries in order, each directory replaced by its
 * importable files, so for a request that names files alone it is the request.
 */
export type LedgerImportSourceDigest = {
  file_index: number;
  sha256: ContentDigest;
};

/**
 * Safe source verification facts without a caller-controlled path.
 */
export type LedgerImportSourceProjection = {
  requested: boolean;
  sha256: ContentDigest | null;
};

/**
 * The account one planned file's statement names, by mask only.
 *
 * `own_account_id` is the registered own account the statement names;
 * `registrable` says the statement names a valid account that no registered
 * account has. The full account number never leaves the secure request.
 */
export type LedgerImportStatementAccount = {
  file_index: number;
  masked_iban: string;
  own_account_id: string | null;
  registrable: boolean;
};

/**
 * Bounded validation facts, with provider warning prose withheld.
 */
export type LedgerImportValidationProjection = {
  valid: boolean;
  warning_count: number;
  encoding: string | null;
};

/**
 * Canonical provider ID strings accepted by the ledger import dispatch.
 *
 * Each token names the parser it selects: `auto` is the only token that runs
 * detection, and a format token never stands for another format. No token
 * names a bank: `pdf` reads a PDF statement of any bank's layout.
 */
export type LedgerProviderID =
  "auto" | "csv" | "ofx" | "qfx" | "xlsx" | "xls" | "pdf";

